def extract_authorization_code(request):
    """
    Get authorization code from the URL parameters.

    Return an authorization code string.
    """
    return request.GET.get('code')


def extract_access_token(request):
    """
    Get access token from the URL parameters.

    Return an access token string.
    """
    return request.GET.get('access_token')


def extract_refresh_token(request):
    """
    Get refresh token from the URL parameters.

    Return a refresh token string.
    """
    return request.GET.get('refresh_token')


def extract_token_request_parameters(request):
    """
    Get token request parameters from the URL parameters.

    Return a dictionary containing token request parameters.
    """
    params = {}
    for key, value in request.GET.items():
        if key.startswith('token'):
            params[key] = value
    return params


def extract_scopes(request):
    """
    Get scopes from the URL parameters.

    Return a list of scopes.
    """
    return request.GET.getlist('scope')


def extract_redirect_uri(request):
    """
    Get redirect URI from the URL parameters.

    Return a redirect URI string.
    """
    return request.GET.get('redirect_uri')


